import { existsSync, readFileSync } from "fs";
import { spawnSync } from "bun";
import { homedir } from "os";
import { join } from "path";
import { defineCommand } from "citty";
import { isAgentCaller, refuseAgentWrite, shouldBlockAgentWrite } from "../agent-detect.js";
import {
  listRoutineSlugs,
  openRoutine,
  readDefaultMcpUrl,
  readRoutine,
  writeDefaultMcpUrl,
  usesMcp,
  writeRoutine,
  writeRoutineJobId,
  deleteRoutine,
} from "../../core/routine.js";
import {
  bootArgs,
  defaultHermesRun,
  editArgs,
  listCronJobs,
  loginCommand,
  MCP_SERVER,
  onePassArgs,
  onePassCommand,
  parseCreatedJobId,
  pauseArgs,
  resumeArgs,
  runsArgs,
  watchCommands,
  type CronJob,
} from "../../core/hermes.js";
import { ui, resolveOutputMode, outJson, summaryLine, guidedError, nextAction, type OutputMode } from "../out.js";
import { exit } from "../render/exit.js";
import { promptSelect } from "../prompt.js";

function hermesInstalled(): boolean {
  try {
    return spawnSync(["which", "hermes"], { stdout: "pipe", stderr: "pipe" }).exitCode === 0;

tool_input.new_string:
async function runRm(slug: string, args: { yes?: boolean; "dry-run"?: boolean; format?: string; json?: boolean; ci?: boolean }): Promise<void> {
  const dryRun = Boolean(args["dry-run"]);
  const yes = Boolean(args.yes);
  if (shouldBlockAgentWrite({ agent: isAgentCaller(), yes, dryRun })) {
    refuseAgentWrite("dora harness rm <slug> --yes");
    await exit(2);
    return;
  }
  if (!yes && !dryRun) {
    if (!process.stdin.isTTY || !process.stderr.isTTY) {
      nextAction(`dora harness rm ${slug} --yes`);
      await exit(2);
      return;
    }
    const ans = await promptSelect(
      `Remove ${slug}?`,
      [
        { value: "no", label: "Keep" },
        { value: "yes", label: "Remove" },
      ],
      "no",
    );
    if (ans !== "yes") {
      summaryLine("Nothing removed.");
      await exit(0);
      return;
    }
  }
  const home = homedir();
  const mode = resolveOutputMode(args);
  let routine;
  try {
    routine = readRoutine(home, slug);
  } catch (e) {
    ui.fail(e instanceof Error ? e.message : String(e));
    nextAction("dora harness list");
    await exit(1);
    return;
  }
  const jobs = hermesInstalled() ? listCronJobs() : [];
  let jobId: string | undefined;
  if (routine.jobId) {
    if (!jobs || jobs.some((j) => j.id === routine.jobId)) jobId = routine.jobId;
  } else {
    jobId = jobs?.find((j) => j.name === slug)?.id;
  }
  if (jobId && !hermesInstalled()) {
    printHermesInstall();
    await exit(2);
    return;
  }
  if (dryRun) {
    if (jobId) ui.info(`  ${formatHermesCmd(removeArgs(jobId))}`);
    ui.info(`  delete ${routine.dir}`);
    if (mode.format === "json") outJson({ slug, dryRun: true, job: jobId ? "remove" : "gone" });
    nextAction(`dora harness rm ${slug} --yes`);
    ui.blank();
    await exit(0);
    return;
  }
  let job: "removed" | "gone" = "gone";
  if (jobId) {
    const r = defaultHermesRun(removeArgs(jobId));
    if (r.exitCode !== 0) {
      const still = listCronJobs();
      if (still === null || still.some((j) => j.id === jobId)) {
        ui.fail(r.stderr.trim() || "Remove failed.");
        nextAction("dora harness list");
        await exit(1);
        return;
      }
    } else {
      job = "removed";
    }
  }
  try {
    deleteRoutine(home, slug);
  } catch (e) {
    ui.fail(e instanceof Error ? e.message : String(e));
    nextAction("dora harness list");
    await exit(1);
    return;
  }
  if (mode.format === "json") {
    outJson({ slug, removed: true, job });
    await exit(0);
    return;
  }
  ui.info(`  Removed ${slug}.`);
  nextAction("dora harness list");
  ui.blank();
  await exit(0);
}

export const harnessRm = defineCommand({
  meta: {
    name: "rm",
    description: [
      "Stop the Runtime job and delete the routine folder",
      "",
      "If remove fails and the job is still there, the folder stays.",
      "If the job is already gone, the folder is deleted.",
    ].join("\n"),
  },
  args: WRITE_ARGS,
  async run({ args }) {
    const slug = await pickSlug(args.slug, "rm", " --yes");
    if (!slug) return;
    await runRm(slug, args);
  },
});

